import{_ as t,o as e,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2016-OCT-05 :: Ceph Developer Monthly","description":"","frontmatter":{"title":"2016-OCT-05 :: Ceph Developer Monthly","date":"2016-10-18T00:00:00.000Z","updated":"2016-10-19T00:00:00.000Z","tags":["Ceph","Developer Meeting","Distributed Storage","Memory Pool Allocator","Quality of Service"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2016/2016-OCT-05_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2016/2016-OCT-05_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780459816000}'),p={name:"posts/2016/2016-OCT-05_-_-_Ceph_Developer_Monthly.md"};function i(s,o,n,a,_,g){return e(),l("div",null,[...o[0]||(o[0]=[r("<p>会议纪要</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Sage、Adam、Erika、Nitin、Josh等</p><p><strong>会议主题</strong>： 讨论Ceph分布式存储的开发进展、主要议题及后续行动计划</p><p><strong>一、主要议题</strong></p><ol><li><p><strong>内存池分配器信息</strong><br> Sage介绍了新的内存池分配器，通过宏定义实现对象在正确内存池中的分配，并支持在编译时开启调试模式以追踪对象分配情况。该分配器旨在解决内存碎片化问题，并通过统计内存分配情况来实现内存压力管理。目前已将部分类型转换为使用该分配器，并计划进行性能分析以确保没有引入额外开销。</p></li><li><p><strong>Boost Pool和Slop Containers</strong><br> Sage提到Boost Pool和Slop Containers已基本准备好合并，它们使用了类似内存池分配器的技术。合并后，需要确定在哪些地方使用它们以优化内存分配。</p></li><li><p><strong>BD设备查询接口</strong><br> Nitin介绍了为BD设备添加查询接口的计划，该接口将用于在RBD接口中查询BD设备的唯一ID等信息。该接口的实现需要涉及libceph库、RBD类方法、OSD等方面的修改。</p></li><li><p><strong>服务质量（QoS）更新</strong><br> Josh介绍了使用DM Block算法实现QoS的计划，旨在为不同客户端提供服务质量保证。目前主要关注区分背景I/O和客户端I/O，以及集群恢复过程中的I/O操作。Erika正在对该算法进行性能测试，并计划分享测试结果。</p></li></ol><p><strong>二、决定事项</strong></p><ol><li>继续推进内存池分配器的开发，并进行性能分析。</li><li>合并Boost Pool和Slop Containers，并确定使用场景。</li><li>推进BD设备查询接口的开发。</li><li>继续推进QoS算法的开发，并进行性能测试。</li></ol><p><strong>三、后续行动计划</strong></p><ol><li>Sage负责内存池分配器的性能分析。</li><li>Sage和Boost Pool/Slop Containers的开发者确定使用场景。</li><li>Nitin负责BD设备查询接口的开发。</li><li>Erika和Josh继续推进QoS算法的开发和性能测试。</li></ol><p><strong>四、其他事项</strong></p><ol><li>会议将持续关注蓝鲸存储（Blue Store）的开发进展。</li><li>鼓励开发者积极参与蓝图讨论，并提前在Wiki上进行讨论。</li></ol><p><strong>五、下次会议</strong></p><p>下次Ceph开发者月度会议将于2023年11月2日举行，时间为东部时间晚上9点。会议将重点关注蓝图讨论。</p>",14)])])}const C=t(p,[["render",i]]);export{h as __pageData,C as default};
